export const BUILD=[{id:'anvil',name:'碎砧',sub:'裂甲 · 重击',skills:['break','heavy','interrupt'],bonus:'2 件：攻击 +15%；4 件：重锻击伤害 +45%。'},{id:'rune',name:'炉纹',sub:'铭火 · 引燃',skills:['mark','ignite','interrupt'],bonus:'2 件：灼烧 +30%；4 件：引燃伤害 +50%。'},{id:'guard',name:'守冢',sub:'坚守 · 反击',skills:['guard','break','interrupt'],bonus:'2 件：护甲 +25%；4 件：反击附加 40% 攻击。'}];
export const SKILLS={break:{name:'裂甲锤',icon:'⌁',cd:4,desc:'造成 120% 攻击伤害，削减目标 25% 护甲，持续 6 回合。'},heavy:{name:'重锻击',icon:'✦',cd:5,desc:'造成 220% 攻击伤害，攻击破甲目标再提高 25%。'},interrupt:{name:'断势',icon:'ϟ',cd:6,desc:'造成 115% 攻击伤害，打断下一次蓄力重击。'},mark:{name:'铭火',icon:'♨',cd:4,desc:'造成 90% 攻击伤害，附加持续 5 回合灼烧。'},ignite:{name:'引燃',icon:'✧',cd:5,desc:'造成 160% 攻击伤害，灼烧目标额外受到 80% 攻击伤害。'},guard:{name:'坚守',icon:'▣',cd:5,desc:'造成 100% 攻击伤害，3 回合内减伤 40% 并反击。'}};
export const LOCS=[{name:'失落驿道',en:'THE FORSAKEN ROAD',desc:'沿着车辙，追查消失的黑炉商队。',enemy:'灰旗劫掠者',boss:'灰旗首领 · 沃恩',hp:100,atk:9,armor:7,mat:'铁屑',tag:'金属',reward:18},{name:'熄火矿井',en:'THE HOLLOW FORGE',desc:'熔炉已经冷却，矿井深处仍有锤声。',enemy:'失控矿傀',boss:'炉心守卫 · 断铸',hp:170,atk:14,armor:20,mat:'炉火晶',tag:'火焰',reward:28},{name:'旧誓墓园',en:'THE OATHBOUND GRAVES',desc:'破碎盟约的见证者，沉睡于灰冠之下。',enemy:'失誓卫兵',boss:'守誓者 · 莫尔',hp:250,atk:20,armor:12,mat:'誓约残片',tag:'灵魂',reward:40}];
export const SLOTS=['weapon','helm','armor','ring'];export const SLOTNAME={weapon:'武器',helm:'头盔',armor:'护甲',ring:'戒指'};export const RARITY=['普通','精良','稀有','史诗','传说'];
const uid=()=>Math.random().toString(36).slice(2,10); const rand=(a,b)=>Math.floor(a+Math.random()*(b-a+1));
export function item(slot,level=1,set=null,rarity=1){const mult=1+rarity*.16;return {id:uid(),slot,set,rarity,level,name:(rarity===4?'王烬·':set?BUILD.find(b=>b.id===set).name+'·':'旅铸·')+({weapon:'战锤',helm:'铁盔',armor:'板甲',ring:'指环'}[slot]),atk:Math.round((slot==='weapon'?11:3)*mult+level*1.5),armor:Math.round((slot==='armor'?9:2)*mult+level),hp:Math.round((slot==='helm'?24:9)*mult+level*3),locked:false,bless:0};}
export function fresh(){let inv=BUILD.flatMap(b=>SLOTS.map(s=>item(s,1,b.id,1)));let s={version:1,hero:'布洛克',level:1,xp:0,gold:100,location:0,build:'anvil',inventory:inv,equip:Object.fromEntries(inv.slice(0,4).map(i=>[i.slot,i.id])),skills:['break','heavy','interrupt'],conditions:['always','always','charge'],materials:{'铁屑':5,'炉火晶':2,'誓约残片':1},talents:{power:0,heart:0,steel:0},kills:0,bossWins:[0,0,0],bossReady:[0,0,0],stock:3,chapters:[],chronicle:['灰冠历 317 年：你离开黑炉堡，寻找失踪商队。'],lastSeen:Date.now(),running:false};return s;}
export function stats(s){let gear=Object.values(s.equip).map(id=>s.inventory.find(i=>i.id===id)).filter(Boolean),count={};gear.forEach(i=>{if(i.set)count[i.set]=(count[i.set]||0)+1});let atk=14+s.level*3+s.talents.power*3+gear.reduce((n,i)=>n+i.atk+(i.bless||0)*2,0);let armor=5+s.level+s.talents.steel*3+gear.reduce((n,i)=>n+i.armor,0);let hp=120+s.level*14+s.talents.heart*20+gear.reduce((n,i)=>n+i.hp,0);if(count.anvil>=2)atk*=1.15;if(count.guard>=2)armor*=1.25;return {atk:Math.round(atk),armor:Math.round(armor),hp:Math.round(hp),count,legend:gear.some(i=>i.rarity===4)};}
export function preset(s,id){const b=BUILD.find(b=>b.id===id);s.build=id;s.skills=[...b.skills];s.conditions=b.id==='guard'?['always','always','charge']:['always','always','charge'];for(let slot of SLOTS){const candidates=s.inventory.filter(i=>i.slot===slot&&i.set===id);candidates.sort((a,b)=>(b.atk+b.armor+b.hp/5)-(a.atk+a.armor+a.hp/5));if(candidates[0])s.equip[slot]=candidates[0].id;}return b;}
export function encounter(s,boss=false){const l=LOCS[s.location],st=stats(s);return {boss,name:boss?l.boss:l.enemy,hp:l.hp*(boss?4:1),max:l.hp*(boss?4:1),atk:l.atk*(boss?1.65:1),armor:l.armor*(boss?1.3:1),heroHp:st.hp,round:0,burn:0,broken:0,guard:0,stun:0,cd:{},done:false};}
const damage=(raw,armor)=>Math.max(1,Math.round(raw*100/(100+Math.max(0,armor))));
export function step(s,e){if(e.done)return[];let st=stats(s),logs=[];e.round++;for(let k in e.cd)e.cd[k]=Math.max(0,e.cd[k]-1);let charge=e.round%4===0;let ix=s.skills.findIndex((k,i)=>!e.cd[k]&&(s.conditions[i]!=='low'||e.heroHp<st.hp*.6)&&(s.conditions[i]!=='charge'||charge)&&(s.conditions[i]!=='burn'||e.burn>0));let k=ix<0?null:s.skills[ix],raw=st.atk,extra=0;if(k){e.cd[k]=SKILLS[k].cd;if(k==='break'){raw*=1.2;e.broken=6;}if(k==='heavy')raw*=2.2*(e.broken?1.25:1)*(st.count.anvil>=4?1.45:1);if(k==='mark'){raw*=.9;e.burn=5;}if(k==='ignite')raw*= (e.burn?2.4:1.6)*(st.count.rune>=4?1.5:1);if(k==='guard')e.guard=3;if(k==='interrupt'){raw*=1.15;if(charge)e.stun=1;}}if(st.legend)extra=Math.min(e.max*.01,st.atk*.6);let dealt=damage(raw,e.armor*(e.broken?.75:1))+Math.round(extra);e.hp-=dealt;logs.push((k?SKILLS[k].name:'普通攻击')+' · '+dealt+' 伤害');if(e.burn>0){let dot=damage(st.atk*.32*(st.count.rune>=2?1.3:1),e.armor*.5);e.hp-=dot;logs.push('炉火灼烧 · '+dot);e.burn--;}if(e.hp<=0){e.hp=0;e.done=true;e.win=true;return logs;}if(e.stun){logs.push('敌人蓄力被打断');e.stun=0;}else{let hurt=damage(e.atk*(charge?2:1),st.armor)*(e.guard>0?.6:1);hurt=Math.max(1,Math.round(hurt));e.heroHp-=hurt;logs.push((charge?'敌人重击':'敌人攻击')+' · -'+hurt);if(e.guard>0){let counter=damage(st.atk*(st.count.guard>=4?1.0:.6),e.armor);e.hp-=counter;logs.push('坚守反击 · '+counter);}}e.guard=Math.max(0,e.guard-1);e.broken=Math.max(0,e.broken-1);if(e.heroHp<=0){e.heroHp=0;e.done=true;e.win=false;}else if(e.hp<=0){e.hp=0;e.done=true;e.win=true;}return logs;}
export function gainXp(s,n){s.xp+=n;while(s.xp>=s.level*80){s.xp-=s.level*80;s.level++;}}
export function reward(s,e,now=Date.now()){if(!e.win)return null;let l=LOCS[s.location];s.kills++;s.gold+=l.reward*(e.boss?5:1);gainXp(s,e.boss?100:20+s.location*8);s.materials[l.mat]+=e.boss?4:1;let drop=null;if(e.boss||Math.random()<.4){if(s.inventory.length<100){const roll=Math.random();let rarity=e.boss?(roll<.12?4:roll<.6?3:2):(roll<.02?4:roll<.14?3:roll<.4?2:1);drop=item(SLOTS[rand(0,3)],s.level,Math.random()<.7?BUILD[rand(0,2)].id:null,rarity);s.inventory.push(drop);}}if(e.boss){s.bossWins[s.location]++;s.bossReady[s.location]=now+60000;if(!s.chapters.includes(s.location)){s.chapters.push(s.location);s.chronicle.unshift(['沃恩交出了商队货单：货物并非被抢，而是被人改道。','地精技师「尼克」从炉芯发现了烬裔封印。','精灵信使「瑟拉」证实：旧盟约的碎片，正在被五族争夺。'][s.location]);}}return drop;}
export function offline(s,now=Date.now()){let elapsed=Math.min(4*3600000,Math.max(0,now-s.lastSeen));s.lastSeen=now;if(!s.running||elapsed<30000)return null;let cycles=Math.floor(elapsed/15000),l=LOCS[s.location];let gold=cycles*Math.floor(l.reward*.45),xp=cycles*8,mat=Math.floor(cycles/3);s.gold+=gold;gainXp(s,xp);s.materials[l.mat]+=mat;s.chronicle.unshift('离线驻扎：商队侦察员带回 '+gold+' 金币与 '+mat+' '+l.mat+'。');s.chronicle=s.chronicle.slice(0,20);return {minutes:Math.floor(elapsed/60000),gold,xp,mat};}
export function forge(s,selection,slot){if(selection.length<1||selection.length>5||s.gold<40)return null;let counts={};selection.forEach(k=>counts[k]=(counts[k]||0)+1);if(Object.entries(counts).some(([k,v])=>!(k in s.materials)||s.materials[k]<v))return null;if(s.inventory.length>=100)return null;Object.entries(counts).forEach(([k,v])=>s.materials[k]-=v);s.gold-=40;let main=Object.entries(counts).sort((a,b)=>b[1]-a[1])[0][0],set={'铁屑':'anvil','炉火晶':'rune','誓约残片':'guard'}[main],r=Math.random();let rarity=r<.02?4:r<.15+selection.length*.04?3:2;let it=item(slot,s.level+rand(0,2),set,rarity);s.inventory.push(it);return it;}
export function validSave(s){try{const num=(n,max=1e12)=>Number.isFinite(n)&&n>=0&&n<=max;return s.version===1&&s.hero==='布洛克'&&Number.isInteger(s.level)&&s.level>=1&&s.level<100000&&num(s.xp)&&num(s.gold)&&Number.isInteger(s.location)&&s.location>=0&&s.location<3&&Array.isArray(s.inventory)&&s.inventory.length>=4&&s.inventory.length<=100&&s.inventory.every(i=>typeof i.id==='string'&&typeof i.name==='string'&&SLOTS.includes(i.slot)&&Number.isInteger(i.rarity)&&i.rarity>=0&&i.rarity<=4&&(!i.set||BUILD.some(b=>b.id===i.set))&&num(i.atk)&&num(i.hp)&&num(i.armor)&&num(i.level)&&num(i.bless,5))&&new Set(s.inventory.map(i=>i.id)).size===s.inventory.length&&SLOTS.every(k=>s.inventory.some(i=>i.id===s.equip[k]&&i.slot===k))&&Array.isArray(s.skills)&&s.skills.length===3&&new Set(s.skills).size===3&&s.skills.every(k=>SKILLS[k])&&Array.isArray(s.conditions)&&s.conditions.length===3&&s.conditions.every(k=>['always','low','charge','burn'].includes(k))&&LOCS.every(l=>num(s.materials[l.mat]))&&['power','heart','steel'].every(k=>Number.isInteger(s.talents[k])&&num(s.talents[k],s.level))&&Object.values(s.talents).reduce((a,b)=>a+b,0)<=s.level-1&&['bossWins','bossReady'].every(k=>Array.isArray(s[k])&&s[k].length===3&&s[k].every(n=>num(n,1e15)))&&Array.isArray(s.chapters)&&s.chapters.every(n=>Number.isInteger(n)&&n>=0&&n<3)&&Array.isArray(s.chronicle)&&s.chronicle.length<=100&&s.chronicle.every(t=>typeof t==='string'&&t.length<2000)&&num(s.kills)&&num(s.stock,3)&&num(s.lastSeen,1e15)&&typeof s.running==='boolean';}catch{return false;}}
